import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        long total = 0;
        long[] diff = new long[m + 2];

        for (int i = 0; i < n - 1; i++) {
            int from = a[i];
            int to = a[i + 1];
            if (from == to) continue;

            int direct = (to - from + m) % m;
            total += direct;

            if (direct > 1) {
                int shortcutStart = (from + 2) % m;
                int shortcutEnd = (to + 1) % m;
                if (shortcutStart <= shortcutEnd) {
                    diff[shortcutStart] += direct - 1;
                    diff[shortcutEnd + 1] -= direct - 1;
                } else {
                    diff[shortcutStart] += direct - 1;
                    diff[m] -= direct - 1;
                    diff[0] += direct - 1;
                    diff[shortcutEnd + 1] -= direct - 1;
                }
            }
        }

        long maxSaving = 0;
        long current = 0;
        for (int i = 0; i < m; i++) {
            current += diff[i];
            if (current > maxSaving) {
                maxSaving = current;
            }
        }

        System.out.println(total - maxSaving);
    }
}

