        long maxSaving = 0;
        for (int xi = 1; xi <= m; xi++) {
            // Only try x = a[i] values
            int x = xi; // This would be O(m), too slow
            break;
        }
        // Try each a[i] as x
        for (int j = 0; j < n; j++) {
            int x = a[j];
            long saving = 0;
            for (int i = 0; i < n-1; i++) {
                long direct = ((long)(a[i+1] - a[i] + m)) % m;
                long withFav = 1 + ((long)(a[i+1] - x + m)) % m;
                saving += Math.max(0, direct - withFav);
            }
            maxSaving = Math.max(maxSaving, saving);
        }
        System.out.println(base - maxSaving);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int m = fs.nextInt();

        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = fs.nextInt();

        long base = 0; // cost using only forward button
        long[] gain = new long[m + 2]; // gain[x] = total saved presses if favorite level is x

        for (int i = 0; i < n - 1; i++) {
            int s = a[i];
            int t = a[i + 1];

            int d = t - s;
            if (d < 0) d += m;   // forward-only cost from s to t
            base += d;

            // Using favorite x is beneficial only if x is encountered before reaching t,
            // and then pressing favorite once is cheaper than continuing by forward.
            // This happens for x in the circular interval (s, t] if not wrapped,
            // or (s, m] U [1, t] if wrapped.
            // For such x, saving = d - 1 - dist(s, x), where dist(s, x) is forward distance.
            //
            // Let y = dist(s, x), then y ranges 1..d, and saving = d-1-y.
            // Positive only for y <= d-2.
            // So for y = 1..d-2, add (d-1-y).
            if (d >= 2) {
                // x = s + y (mod m), y in [1, d-2]
                // saving = (d-1) - y
                // This is a linear function on a circular interval.
                addLinearCircular(gain, m, s + 1, s + d - 2, -(long)1, (long)(d - 1 + s));
            }
        }

        long bestGain = 0;
        for (int x = 1; x <= m; x++) {
            bestGain = Math.max(bestGain, gain[x]);
        }

        System.out.println(base - bestGain);
    }

    // Add value A*i + B to each position i on circular interval [l, r] modulo m, positions are 1..m.
    static void addLinearCircular(long[] arr, int m, int l, int r, long A, long B) {
        l = norm(l, m);
        r = norm(r, m);
        if (l <= r) {
            addRangeLinear(arr, l, r, A, B);
        } else {
            addRangeLinear(arr, l, m, A, B);
            addRangeLinear(arr, 1, r, A, B);
        }
    }

    // Difference-array style for linear function on [l, r]:
    // add A*i + B to each i in [l, r]
    static void addRangeLinear(long[] diff, int l, int r, long A, long B) {
        diff[l] += A * l + B;
        if (r + 1 < diff.length) diff[r + 1] -= A * l + B;

        if (l + 1 < diff.length) diff[l + 1] += A;
        if (r + 1 < diff.length) diff[r + 1] -= A;
    }

    static int norm(int x, int m) {
        x %= m;
        if (x <= 0) x += m;
        return x;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

