int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, m;
    cin >> n >> m;
    vector<int64> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    int64 total = 0;
    // candidate favorite levels: a[i] + 1 (mod m)
    vector<int64> candidates;
    for (int i = 0; i < n - 1; i++) {
        int64 from = a[i];
        int64 to = a[i+1];
        int64 cost = (to - from + m) % m;
        total += cost;
        candidates.push_back((from + 1) % m);
    }
    // also try a[0] maybe
    candidates.push_back(a[0]);

    int64 max_save = 0;
    for (int64 x : candidates) {
        int64 save = 0;
        for (int i = 0; i < n - 1; i++) {
            int64 from = a[i];
            int64 to = a[i+1];
            int64 cost = (to - from + m) % m;
            int64 new_cost = ((x - from + m) % m) + 1 + ((to - x + m) % m);
            save += cost - new_cost;
        }
        max_save = max(max_save, save);
    }

    cout << total - max_save << "\n";

    return 0;
