using namespace std;
int main(){
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for(auto &x: a) cin >> x;

    long long base = 0;
    vector<long long> val(m+2, 0), slope(m+2, 0);

    for(int i = 0; i < n-1; i++){
        int u = a[i], v = a[i+1];
        int d = (v - u + m) % m;
        base += d;
        if(d <= 1) continue;
        // x in [v-(d-2), v] mod m, saving = d-1-(v-x+m)%m
        int L = ((v - (d-2) - 1 + m) % m) + 1; // 1-indexed
        int R = v;
        // saving at L = 1, at R = d-1, increases by 1
        if(L <= R){
            slope[L]++; slope[R+1]--;
            val[L] += 1; val[R+1] -= (long long)d;
        } else {
            slope[1]++; slope[R+1]--;
            val[1] += (long long)(d - (m - L + 1)); val[R+1] -= (long long)d;
            slope[L]++; slope[m+1]--;
            val[L] += 1; val[m+1] -= (long long)(d - (R));
        }
    }
    long long best = 0, cur_slope = 0, cur_val = 0;
    for(int x = 1; x <= m; x++){
        cur_slope += slope[x]; cur_val += val[x];
        long long s = cur_val + cur_slope * (x - 1);
        best = max(best, s);
    }
    cout << base - best << endl;
}

