using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m;
    cin >> n >> m;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    // Base cost: using only the forward button.
    long long base = 0;
    for (int i = 0; i + 1 < n; i++) {
        long long d = a[i + 1] - a[i];
        if (d < 0) d += m;
        base += d;
    }

    // gain[x] = total reduction in presses if favorite level is x.
    // Use difference array on [1..m].
    vector<long long> diff(m + 3, 0);

    auto add_range = [&](long long l, long long r, long long v) {
        if (l > r) return;
        diff[l] += v;
        diff[r + 1] -= v;
    };

    for (int i = 0; i + 1 < n; i++) {
        long long s = a[i], t = a[i + 1];
        long long d = t - s;
        if (d < 0) d += m;

        // If choosing favorite x on the forward path from s to t (excluding s, including t),
        // then cost becomes 1 + distance(x, t), so reduction is d - (1 + distance(x, t)).
        // This equals steps from s to x minus 1, increasing by 1 along the path.
        // Let k = number of steps from s to x, where 1 <= k <= d.
        // gain += k - 1.
        if (d <= 1) continue; // no positive gain possible

        if (s < t) {
            // Path is [s+1 .. t]
            // gain on x in [s+1 .. t]: (x - s) - 1 = x - s - 1
            // = (+1)*x + constant, but we only need final values.
            // Implement via:
            // on [s+1, t], add sequence 0,1,2,...,d-1
            // Easier with two diff arrays would be linear function,
            // but constraints here allow O(n + m) only if we use a direct trick:
            // gain[x] += x on range, and subtract constant on range.
        } else {
            // wrapped path
        }
    }

    // To support range add of linear function ax+b, use two difference arrays.
    vector<long long> diffA(m + 3, 0), diffB(m + 3, 0);

    auto add_linear = [&](long long l, long long r, long long A, long long B) {
        if (l > r) return;
        diffA[l] += A;
        diffA[r + 1] -= A;
        diffB[l] += B;
        diffB[r + 1] -= B;
    };

    for (int i = 0; i + 1 < n; i++) {
        long long s = a[i], t = a[i + 1];
        long long d = t - s;
        if (d < 0) d += m;
        if (d <= 1) continue;

        if (s < t) {
            // x in [s+1, t]: gain = x - s - 1
            add_linear(s + 1, t, 1, -s - 1);
        } else {
            // x in [s+1, m]: gain = x - s - 1
            add_linear(s + 1, m, 1, -s - 1);
            // x in [1, t]: gain = (m - s + x) - 1 = x + (m - s - 1)
            add_linear(1, t, 1, m - s - 1);
        }
    }

    long long bestGain = 0;
    long long curA = 0, curB = 0;
    for (long long x = 1; x <= m; x++) {
        curA += diffA[x];
        curB += diffB[x];
        long long gain = curA * x + curB;
        bestGain = max(bestGain, gain);
    }

    cout << base - bestGain << '\n';
    return 0;
}

