#include <stdlib.h>

#define min(a,b) ((a)<(b)?(a):(b))
#define MAXN 200005
#define MAXM 100005

int a[MAXN];
long long forwardCost[MAXN];

int main() {
    int n, m;
    scanf("%d %d", &n, &m);

    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    long long totalForward = 0;
    for (int i = 0; i < n - 1; i++) {
        int diff = (a[i+1] - a[i] + m) % m;
        forwardCost[i] = diff;
        totalForward += diff;
    }

    long long ans = totalForward;

    // For each possible x from 1 to m, compute total cost
    // We'll use an array to accumulate savings relative to using forward only
    long long *savings = (long long*)calloc(m + 2, sizeof(long long));

    for (int i = 0; i < n - 1; i++) {
        int from = a[i];
        int to = a[i+1];
        int diff = (to - from + m) % m;

        // Without favorite: cost = diff
        // With favorite x: cost = 1 + (to - x + m) % m
        // Saving = diff - (1 + (to - x + m) % m)
        // We want to add saving for each x.
        // For a fixed transition, the saving as function of x:
        // If x == to: cost = 1, saving = diff - 1
        // If x != to: cost = 1 + (to - x + m) % m, saving = diff - 1 - (to - x + m) % m
        // We can compute range where saving is positive.

        // Simpler approach: For each possible x, compute directly? m up to 1e5, n up to 2e5 -> O(m*n) too big.
        // Instead, use difference array for savings.

        // If from == to, cost is always 0, favorite doesn't help.
        if (diff == 0) continue;

        // Without favorite cost = diff
        // With favorite: 
        // If x == to: cost = 1
        // else: cost = 1 + (to - x + m) % m
        // We add saving as (diff - cost) for each x.

        // Let's handle x == to separately
        savings[to] += diff - 1;

        // For x != to:
        // saving = diff - 1 - ((to - x + m) % m)
        // Let d = (to - x + m) % m, ranges 1..m-1
        // saving = diff - 1 - d
        // We add this for each d in 1..m-1, but diff-1-d positive only when d < diff-1.
        // So for d = 1 to diff-2: saving positive.
        // d = (to - x + m) % m => x = (to - d + m) % m
        // So for each d in 1..diff-2:
        //   x = (to - d + m) % m; if x == 0 then x = m.
        // Add saving = diff-1-d to savings[x].

        // Since m up to 1e5, diff up to m, we can loop d.
        for (int d = 1; d < diff; d++) {
            int x = (to - d + m) % m;
            if (x == 0) x = m;
            savings[x] += diff - 1 - d;
        }
    }

    long long bestSaving = 0;
    for (int x = 1; x <= m; x++) {
        if (savings[x] > bestSaving) bestSaving = savings[x];
    }

    ans = totalForward - bestSaving;
    printf("%lld\n", ans);

    free(savings);
    return 0;
}

