#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int n;
    ll m;
    if (scanf("%d %lld", &n, &m) != 2) return 0;

    ll *a = (ll *)malloc(sizeof(ll) * n);
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);

    ll base = 0;
    ll *cand = (ll *)malloc(sizeof(ll) * (2 * n + 5));
    int k = 0;

    for (int i = 0; i + 1 < n; i++) {
        ll d = (a[i + 1] - a[i] + m) % m;   // forward-only cost
        base += d;

        // If using favorite x before moving to a[i+1], cost becomes:
        // 1 + (a[i+1] - x + m) % m
        // Improvement positive when x is in [1..a[i+1]-1] or [a[i]+1..m] depending on wrap.
        // This can be represented on a circle by interval (a[i], a[i+1]) clockwise.
        if (d >= 2) {
            ll l = a[i] + 1;
            ll r = a[i + 1] - 1;
            if (r >= l) {
                cand[k++] = l;
                cand[k++] = r + 1;
            } else {
                // wrapped interval: [1..r] U [l..m]
                cand[k++] = 1;
                cand[k++] = r + 1;
                cand[k++] = l;
                cand[k++] = m + 1;
            }
        }
    }

    // Sweep difference on [1..m]
    qsort(cand, k, sizeof(ll), cmp_ll);

    // Need weighted events, so rebuild properly
    // We'll store events (pos, delta) in arrays.
    free(cand);

    int maxe = 4 * n + 10;
    ll *pos = (ll *)malloc(sizeof(ll) * maxe);
    ll *delta = (ll *)malloc(sizeof(ll) * maxe);
    int e = 0;

    for (int i = 0; i + 1 < n; i++) {
        ll d = (a[i + 1] - a[i] + m) % m;
        if (d >= 2) {
            // Improvement for x in clockwise interval from a[i]+1 to a[i+1]-1:
            // gain = d - 1 - dist(x, a[i+1])
            // Over that interval, as x increases clockwise, gain increases by 1 each step.
            // Equivalent total contribution can be swept by counting active intervals
            // after transforming value:
            // gain(x) = x - a[i] - 1 on non-wrap part; similarly on wrap.
            ll l = a[i] + 1;
            ll r = a[i] + d - 1; // on unfolded line
            // interval on unfolded coordinates [l, r], gain = t - a[i] - 1
            // map to circle by possibly splitting with period m
            while (l > m) { l -= m; r -= m; }
            if (r <= m) {
                // add linear function +x + const on [l, r]
                pos[e] = l; delta[e++] = 1;
                pos[e] = r + 1; delta[e++] = -1;
            } else {
                pos[e] = l; delta[e++] = 1;
                pos[e] = m + 1; delta[e++] = -1;
                pos[e] = 1; delta[e++] = 1;
                pos[e] = (r - m) + 1; delta[e++] = -1;
            }
        }
    }

    // The above only counts number of active intervals, but actual gain depends on x and starts.
    // Simpler correct approach:
    // For each transition with distance d, for every x on the clockwise path excluding endpoints,
    // gain at x is 1,2,...,d-1 along the path. This can be added by range-add arithmetic progression.
    // We'll do difference arrays on events of slope/intercept over [1..m].

    free(pos);
    free(delta);

    pos = (ll *)malloc(sizeof(ll) * maxe * 2);
    delta = (ll *)malloc(sizeof(ll) * maxe * 2); // reused as coeff storage
    ll *deltaB = (ll *)malloc(sizeof(ll) * maxe * 2);
    e = 0;

    for (int i = 0; i + 1 < n; i++) {
        ll d = (a[i + 1] - a[i] + m) % m;
        if (d < 2) continue;

        ll s = a[i];
        ll l = s + 1;
        ll r = s + d - 1; // unfolded interval
        // gain(t) = t - s on unfolded coordinates
        while (l > m) { l -= m; r -= m; s -= m; }

        if (r <= m) {
            pos[e] = l;     delta[e] = 1;  deltaB[e++] = -s;
            pos[e] = r + 1; delta[e] = -1; deltaB[e++] = s;
        } else {
            pos[e] = l;     delta[e] = 1;  deltaB[e++] = -s;
            pos[e] = m + 1; delta[e] = -1; deltaB[e++] = s;

            pos[e] = 1;             delta[e] = 1;  deltaB[e++] = -(s + m);
            pos[e] = (r - m) + 1;   delta[e] = -1; deltaB[e++] = (s + m);
        }
    }

    // sort events by pos
    int *ord = (int *)malloc(sizeof(int) * e);
    for (int i = 0; i < e; i++) ord[i] = i;
    // simple qsort on indices by pos
    int cmp_idx(const void *A, const void *B) {
        int i = *(const int *)A;
        int j = *(const int *)B;
        if (pos[i] < pos[j]) return -1;
        if (pos[i] > pos[j]) return 1;
        return 0;
    }
    qsort(ord, e, sizeof(int), cmp_idx);

    ll curA = 0, curB = 0;
    ll best = 0;
    int p = 0;

    for (ll x = 1; x <= m; ) {
        while (p < e && pos[ord[p]] == x) {
            int id = ord[p];
            curA += delta[id];
            curB += deltaB[id];
            p++;
        }

        ll next = (p < e ? pos[ord[p]] : m + 1);
        if (next > m + 1) next = m + 1;

        // On [x, next-1], total gain = curA * t + curB, linear in t.
        // Maximum on integer interval occurs at an endpoint.
        if (x <= m) {
            ll g1 = curA * x + curB;
            if (g1 > best) best = g1;
            ll y = next - 1;
            if (y >= x && y <= m) {
                ll g2 = curA * y + curB;
                if (g2 > best) best = g2;
            }
        }
        x = next;
    }

    printf("%lld\n", base - best);

    free(a);
    free(pos);
    free(delta);
    free(deltaB);
    free(ord);
    return 0;
}
